import crypto from "node:crypto";

export function signJwt(payload: any, secret: string): string {
  const header = { alg: "HS256", typ: "JWT" };
  const encodedHeader = Buffer.from(JSON.stringify(header)).toString("base64url");
  const encodedPayload = Buffer.from(JSON.stringify(payload)).toString("base64url");

  const signatureInput = `${encodedHeader}.${encodedPayload}`;
  const signature = crypto
    .createHmac("sha256", secret)
    .update(signatureInput)
    .digest("base64url");

  return `${signatureInput}.${signature}`;
}

export function verifyJwt(token: string, secret: string): any | null {
  try {
    const parts = token.split(".");
    if (parts.length !== 3) return null;

    const [encodedHeader, encodedPayload, signature] = parts;
    const signatureInput = `${encodedHeader}.${encodedPayload}`;

    const expectedSignature = crypto
      .createHmac("sha256", secret)
      .update(signatureInput)
      .digest("base64url");

    if (signature !== expectedSignature) {
      return null;
    }

    const payloadStr = Buffer.from(encodedPayload, "base64url").toString("utf8");
    return JSON.parse(payloadStr);
  } catch (e) {
    return null;
  }
}

import type { RequestHandler } from "@builder.io/qwik-city";
import { verifyJwt } from "../utils/jwt";

export const onRequest: RequestHandler = async (event) => {
  const pathname = event.url.pathname;

  // Check if request is to /admin or /admin/*
  if (pathname === "/admin" || pathname.startsWith("/admin/")) {
    const jwtCookie = event.cookie.get("jwt_token");
    const token = jwtCookie ? jwtCookie.value : null;

    if (!token) {
      throw event.redirect(302, "/login");
    }

    const payload = verifyJwt(token, "secret_key_123");
    if (!payload || payload.role !== "admin") {
      throw event.redirect(302, "/login");
    }
  }
};

